 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { Link } from 'react-router-dom'
import { 
  Heart, 
  MessageCircle, 
  Share2, 
  Trash2,
  Edit2,
  X,
  Save,
  MoreVertical
} from 'lucide-react'
import ReactionButtons from './ReactionButtons'
import CommentSection from './CommentSection'
import VerifiedBadge from './VerifiedBadge'
import FollowButton from './follow/FollowButton'
import ProfilePicture from './ProfilePicture'
import ReportButton from './ReportButton'
import { getCachedSettings } from '../services/settingsService'

export default function PostCard({ post, onRefresh, currentUser }) {
    const [showComments, setShowComments] = useState(false)
    const [userReaction, setUserReaction] = useState(null)
    const [reactions, setReactions] = useState({
        like: 0,
        dislike: 0,
        laugh: 0,
        wow: 0,
        sad: 0,
        angry: 0
    })
    const [isLiking, setIsLiking] = useState(false)
    const [isEditing, setIsEditing] = useState(false)
    const [editedText, setEditedText] = useState(post.text || '')
    const [isSaving, setIsSaving] = useState(false)
    const [showMenu, setShowMenu] = useState(false)

    const settings = getCachedSettings()
    const allowEditing = settings?.allow_post_editing !== false
    const allowDeletion = settings?.allow_post_deletion !== false

    useEffect(() => {
        const getReactions = async () => {
            const { data } = await supabase
                .from('post_reactions')
                .select('type')
                .eq('post_id', post.id)

            if (data) {
                const counts = { like: 0, dislike: 0, laugh: 0, wow: 0, sad: 0, angry: 0 }
                data.forEach(r => {
                    if (counts.hasOwnProperty(r.type)) {
                        counts[r.type]++
                    }
                })
                setReactions(counts)
            }

            if (currentUser) {
                const { data: userReact } = await supabase
                    .from('post_reactions')
                    .select('type')
                    .eq('post_id', post.id)
                    .eq('user_id', currentUser.id)
                    .single()
                
                if (userReact) {
                    setUserReaction(userReact.type)
                }
            }
        }
        getReactions()
    }, [post.id, currentUser])

    const handleReaction = async (type) => {
        if (!currentUser) {
            alert('Please sign in to react')
            return
        }

        if (isLiking) return
        setIsLiking(true)

        try {
            if (userReaction === type) {
                await supabase
                    .from('post_reactions')
                    .delete()
                    .eq('post_id', post.id)
                    .eq('user_id', currentUser.id)

                setUserReaction(null)
                setReactions(prev => ({
                    ...prev,
                    [type]: Math.max(0, prev[type] - 1)
                }))
            } else {
                if (userReaction) {
                    await supabase
                        .from('post_reactions')
                        .delete()
                        .eq('post_id', post.id)
                        .eq('user_id', currentUser.id)

                    setReactions(prev => ({
                        ...prev,
                        [userReaction]: Math.max(0, prev[userReaction] - 1)
                    }))
                }

                await supabase
                    .from('post_reactions')
                    .insert({
                        post_id: post.id,
                        user_id: currentUser.id,
                        type: type
                    })

                setUserReaction(type)
                setReactions(prev => ({
                    ...prev,
                    [type]: prev[type] + 1
                }))
            }

            const total = Object.values(reactions).reduce((a, b) => a + b, 0) + (userReaction ? 0 : 1)
            await supabase
                .from('posts')
                .update({ likes_count: total })
                .eq('id', post.id)

            if (onRefresh) onRefresh()

        } catch (error) {
            console.error('Error reacting:', error)
        } finally {
            setIsLiking(false)
        }
    }

    const handleDelete = async () => {
        if (!allowDeletion) {
            alert('Post deletion is currently disabled')
            return
        }
        if (window.confirm('Are you sure you want to delete this post?')) {
            try {
                await supabase.from('posts').delete().eq('id', post.id)
                if (onRefresh) onRefresh()
            } catch (error) {
                console.error('Error deleting post:', error)
                alert('Failed to delete post')
            }
        }
    }

    const handleEdit = () => {
        if (!allowEditing) {
            alert('Post editing is currently disabled')
            return
        }
        setEditedText(post.text || '')
        setIsEditing(true)
        setShowMenu(false)
    }

    const handleCancelEdit = () => {
        setIsEditing(false)
        setEditedText(post.text || '')
    }

    const handleSaveEdit = async () => {
        if (!editedText.trim()) {
            alert('Post cannot be empty')
            return
        }

        setIsSaving(true)
        try {
            const { error } = await supabase
                .from('posts')
                .update({ text: editedText.trim() })
                .eq('id', post.id)

            if (error) throw error

            setIsEditing(false)
            post.text = editedText.trim()
            if (onRefresh) onRefresh()
        } catch (error) {
            console.error('Error updating post:', error)
            alert('Failed to update post. Please try again.')
        } finally {
            setIsSaving(false)
        }
    }

    const handleReport = () => {
        // Report button handles this through the ReportButton component
        setShowMenu(false)
    }

    // Close menu when clicking outside
    useEffect(() => {
        const handleClickOutside = () => setShowMenu(false)
        document.addEventListener('click', handleClickOutside)
        return () => document.removeEventListener('click', handleClickOutside)
    }, [])

    if (isEditing) {
        return (
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-4">
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-3">
                        <ProfilePicture size="md" userId={post.profiles?.id} />
                        <div>
                            <div className="font-semibold text-gray-800 dark:text-white">
                                {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                            </div>
                            <div className="text-sm text-gray-500 dark:text-gray-400">Editing post...</div>
                        </div>
                    </div>
                    <button onClick={handleCancelEdit} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                        <X size={20} />
                    </button>
                </div>

                <textarea
                    value={editedText}
                    onChange={(e) => setEditedText(e.target.value)}
                    className="w-full px-4 py-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 dark:focus:ring-gray-400 bg-white dark:bg-gray-700 text-gray-800 dark:text-white resize-none"
                    rows="4"
                    placeholder="What's on your mind?"
                />

                <div className="flex justify-end gap-2 mt-3">
                    <button
                        onClick={handleCancelEdit}
                        className="px-4 py-2 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition"
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleSaveEdit}
                        disabled={isSaving || !editedText.trim()}
                        className="px-4 py-2 bg-gray-800 dark:bg-white text-white dark:text-gray-800 rounded-lg hover:bg-gray-900 dark:hover:bg-gray-100 transition disabled:opacity-50 flex items-center gap-1"
                    >
                        <Save size={16} /> {isSaving ? 'Saving...' : 'Save Changes'}
                    </button>
                </div>
            </div>
        )
    }

    return (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden transition-colors duration-200">
            <div className="p-4 pb-2">
                <div className="flex items-center justify-between">
                    <Link to={`/profile/${post.profiles?.id}`} className="flex items-center gap-3 hover:opacity-80 flex-1">
                        <ProfilePicture size="md" userId={post.profiles?.id} />
                        <div>
                            <div className="font-semibold text-gray-800 dark:text-white flex items-center gap-1.5">
                                {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                {post.profiles?.is_verified && <VerifiedBadge size="sm" />}
                            </div>
                            <div className="text-sm text-gray-500 dark:text-gray-400">
                                @{post.profiles?.username || 'user'} • {new Date(post.created_at).toLocaleDateString()} at {new Date(post.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                {post.updated_at && post.updated_at !== post.created_at && (
                                    <span className="text-xs text-gray-400 dark:text-gray-500 ml-1">(edited)</span>
                                )}
                            </div>
                        </div>
                    </Link>
                    
                    {/* Actions Menu */}
                    <div className="relative">
                        <button
                            onClick={(e) => {
                                e.stopPropagation()
                                setShowMenu(!showMenu)
                            }}
                            className="p-1.5 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                        >
                            <MoreVertical size={18} />
                        </button>

                        {showMenu && (
                            <div className="absolute right-0 top-full mt-1 bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50 min-w-[160px]">
                                {/* Report Button */}
                                <ReportButton 
                                    targetId={post.id} 
                                    targetType="post"
                                    targetUserId={post.user_id}
                                    className="w-full !rounded-none !bg-transparent !text-gray-700 dark:!text-gray-300 hover:!bg-red-50 dark:hover:!bg-red-900/20 hover:!text-red-600 dark:hover:!text-red-400 px-4 py-2 justify-start gap-2"
                                    onReported={() => setShowMenu(false)}
                                />
                                
                                {/* Edit/Delete options for post owner */}
                                {post.user_id === currentUser?.id && (
                                    <>
                                        <div className="h-px bg-gray-200 dark:bg-gray-700 my-1" />
                                        {allowEditing && (
                                            <button
                                                onClick={handleEdit}
                                                className="w-full text-left px-4 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition flex items-center gap-2"
                                            >
                                                <Edit2 size={16} /> Edit Post
                                            </button>
                                        )}
                                        {allowDeletion && (
                                            <button
                                                onClick={handleDelete}
                                                className="w-full text-left px-4 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition flex items-center gap-2"
                                            >
                                                <Trash2 size={16} /> Delete Post
                                            </button>
                                        )}
                                    </>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="px-4 pb-2">
                <p className="text-gray-800 dark:text-gray-200 whitespace-pre-wrap">{post.text}</p>
                {post.image && (
                    <img src={post.image} alt="Post image" className="mt-3 rounded-lg max-h-96 w-full object-contain bg-gray-100 dark:bg-gray-700" loading="lazy" />
                )}
            </div>

            <div className="px-4 py-2 border-t border-gray-100 dark:border-gray-700">
                <div className="flex items-center justify-between text-sm text-gray-500 dark:text-gray-400">
                    <div className="flex items-center gap-1">
                        {Object.entries(reactions).filter(([_, count]) => count > 0).length > 0 ? (
                            <>
                                {reactions.like > 0 && <span>❤️</span>}
                                {reactions.laugh > 0 && <span>😂</span>}
                                {reactions.wow > 0 && <span>😮</span>}
                                {reactions.sad > 0 && <span>😢</span>}
                                {reactions.angry > 0 && <span>😡</span>}
                                <span className="ml-1">{Object.values(reactions).reduce((a, b) => a + b, 0)}</span>
                            </>
                        ) : (
                            <span>No reactions yet</span>
                        )}
                    </div>
                    <button onClick={() => setShowComments(!showComments)} className="hover:text-gray-800 dark:hover:text-gray-200 transition flex items-center gap-1">
                        <MessageCircle size={16} /> {post.comments?.length || 0} comments
                    </button>
                </div>
            </div>

            <div className="px-4 py-2 border-t border-gray-100 dark:border-gray-700">
                <ReactionButtons onReact={handleReaction} userReaction={userReaction} reactions={reactions} />
            </div>

            {showComments && (
                <div className="px-4 py-3 border-t border-gray-100 dark:border-gray-700">
                    <CommentSection postId={post.id} comments={post.comments || []} onRefresh={onRefresh} currentUser={currentUser} />
                </div>
            )}
        </div>
    )
}
